import React, { useState, useEffect } from 'react';
import i18n from 'i18next';

// Define the translation resources with all the text for the app.
const resources = {
  en: {
    translation: {
      "app_title": "Fertilizer Recommendation System",
      "app_header": "RECOMMENDING BEST FERTILIZER FOR YOUR CROP",
      "change_language": "Change Language",
      "temperature_label": "Temperature:",
      "humidity_label": "Humidity:",
      "moisture_label": "Moisture:",
      "soil_type_label": "Soil Type:",
      "crop_type_label": "Crop Type:",
      "nitrogen_label": "Nitrogen:",
      "potassium_label": "Potassium:",
      "phosphorous_label": "Phosphorous:",
      "predict_button": "Predict",
      "result_header": "Recommended Fertilizer For Your Crop IS:",
      "default_result": "Fill the form and click 'Predict'",
      "language_en": "English",
      "language_pa": "ਪੰਜਾਬੀ",
      "language_hi": "हिन्दी",
      "switch_to_chat_button": "Switch to Chatbot",
      "switch_to_form_button": "Switch to Form",
      "chat_title": "Chatbot Mode",
      "chat_placeholder": "Type your message here...",
      "chat_send_button": "Send",
      "soil_black": "Black",
      "soil_clayey": "Clayey",
      "soil_loamy": "Loamy",
      "soil_sandy": "Sandy",
      "soil_red": "Red",
      "crop_barley": "Barley",
      "crop_maize": "Maize",
      "crop_wheat": "Wheat",
      "crop_rice": "Rice",
      "crop_cotton": "Cotton"
    }
  },
  pa: {
    translation: {
      "app_title": "ਖਾਦ ਦੀ ਸਿਫ਼ਾਰਸ਼ ਪ੍ਰਣਾਲੀ",
      "app_header": "ਤੁਹਾਡੀ ਫਸਲ ਲਈ ਸਭ ਤੋਂ ਵਧੀਆ ਖਾਦ ਦੀ ਸਿਫਾਰਸ਼ ਕਰ ਰਿਹਾ ਹੈ",
      "change_language": "ਭਾਸ਼ਾ ਬਦਲੋ",
      "temperature_label": "ਤਾਪਮਾਨ:",
      "humidity_label": "ਨਮੀ:",
      "moisture_label": "ਨਮੀ:",
      "soil_type_label": "ਮਿੱਟੀ ਦੀ ਕਿਸਮ:",
      "crop_type_label": "ਫਸਲ ਦੀ ਕਿਸਮ:",
      "nitrogen_label": "ਨਾਈਟ੍ਰੋਜਨ:",
      "potassium_label": "ਪੋਟਾਸ਼ੀਅਮ:",
      "phosphorous_label": "ਫਾਸਫੋਰਸ:",
      "predict_button": "ਅਨੁਮਾਨ ਲਗਾਓ",
      "result_header": "ਤੁਹਾਡੀ ਫਸਲ ਲਈ ਸਿਫਾਰਸ਼ ਕੀਤੀ ਖਾਦ ਹੈ:",
      "default_result": "ਫਾਰਮ ਭਰੋ ਅਤੇ 'ਅਨੁਮਾਨ ਲਗਾਓ' 'ਤੇ ਕਲਿੱਕ ਕਰੋ",
      "language_en": "ਅੰਗਰੇਜ਼ੀ",
      "language_pa": "ਪੰਜਾਬੀ",
      "language_hi": "ਹਿੰਦੀ",
      "switch_to_chat_button": "ਚੈਟਬੋਟ ਤੇ ਬਦਲੋ",
      "switch_to_form_button": "ਫਾਰਮ ਤੇ ਬਦਲੋ",
      "chat_title": "ਚੈਟਬੋਟ ਮੋਡ",
      "chat_placeholder": "ਇੱਥੇ ਆਪਣਾ ਸੁਨੇਹਾ ਟਾਈਪ ਕਰੋ...",
      "chat_send_button": "ਭੇਜੋ",
      "soil_black": "ਕਾਲੀ",
      "soil_clayey": "ਚੀਕਣੀ",
      "soil_loamy": "ਰੇਤਲੀ",
      "soil_sandy": "ਰੇਤਲੀ",
      "soil_red": "ਲਾਲ",
      "crop_barley": "ਜੌਂ",
      "crop_maize": "ਮੱਕੀ",
      "crop_wheat": "ਕਣਕ",
      "crop_rice": "ਚੌਲ",
      "crop_cotton": "ਕਪਾਹ"
    }
  },
  hi: {
    translation: {
      "app_title": "उर्वरक सिफारिश प्रणाली",
      "app_header": "आपकी फसल के लिए सर्वोत्तम उर्वरक की सिफारिश",
      "change_language": "भाषा बदलें",
      "temperature_label": "तापमान:",
      "humidity_label": "आर्द्रता:",
      "moisture_label": "नमी:",
      "soil_type_label": "मिट्टी का प्रकार:",
      "crop_type_label": "फसल का प्रकार:",
      "nitrogen_label": "नाइट्रोजन:",
      "potassium_label": "पोटेशियम:",
      "phosphorous_label": "फास्फोरस:",
      "predict_button": "भविष्यवाणी करें",
      "result_header": "आपकी फसल के लिए अनुशंसित उर्वरक है:",
      "default_result": "फ़ॉर्म भरें और 'भविष्यवाणी करें' पर क्लिक करें",
      "language_en": "अंग्रेज़ी",
      "language_pa": "ਪੰਜਾਬੀ",
      "language_hi": "हिन्दी",
      "switch_to_chat_button": "चैटबॉट पर स्विच करें",
      "switch_to_form_button": "फॉर्म पर स्विच करें",
      "chat_title": "चैटबॉट मोड",
      "chat_placeholder": "यहां अपना संदेश टाइप करें...",
      "chat_send_button": "भेजें",
      "soil_black": "काली",
      "soil_clayey": "चिकनी",
      "soil_loamy": "दोमट",
      "soil_sandy": "रेतीली",
      "soil_red": "लाल",
      "crop_barley": "जौ",
      "crop_maize": "मक्का",
      "crop_wheat": "गेहूं",
      "crop_rice": "चावल",
      "crop_cotton": "कपास"
    }
  }
};

// Initialize i18n
i18n.init({
  compatibilityJSON: 'v3',
  resources,
  lng: 'en', // Set a default language
  fallbackLng: 'en',
  interpolation: {
    escapeValue: false
  }
});

// Map string labels to numerical values for the model
const soilTypeMapping = {
  'Black': 0,
  'Clayey': 1,
  'Loamy': 2,
  'Sandy': 3,
  'Red': 4
};

const cropTypeMapping = {
  'Barley': 0,
  'Maize': 1,
  'Wheat': 2,
  'Rice': 3,
  'Cotton': 4
};

const App = () => {
  const [currentLanguage, setCurrentLanguage] = useState(i18n.language);
  const [isChatMode, setIsChatMode] = useState(false);
  const [inputs, setInputs] = useState({
    temperature: '',
    humidity: '',
    moisture: '',
    soilType: 'Black',
    cropType: 'Barley',
    nitrogen: '',
    potassium: '',
    phosphorous: '',
  });
  const [result, setResult] = useState(i18n.t('default_result'));
  const [isLoading, setIsLoading] = useState(false);
  const [chatHistory, setChatHistory] = useState([]);
  const [chatInput, setChatInput] = useState('');

  useEffect(() => {
    const handleLanguageChange = (lng) => {
      setCurrentLanguage(lng);
      setResult(i18n.t('default_result'));
    };
    i18n.on('languageChanged', handleLanguageChange);
    return () => {
      i18n.off('languageChanged', handleLanguageChange);
    };
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setInputs(prevInputs => ({
      ...prevInputs,
      [name]: value,
    }));
  };

  const handleLanguageChange = (e) => {
    const newLng = e.target.value;
    i18n.changeLanguage(newLng);
  };

  // Function to toggle between Form and Chatbot UI
  const toggleChatMode = () => {
    setIsChatMode(prevMode => !prevMode);
    setResult(i18n.t('default_result'));
  };

  const handleFormPredict = async () => {
    setIsLoading(true);
    setResult("Loading...");

    // Convert string inputs to numerical values for the model
    const dataToSend = {
      ...inputs,
      soilType: soilTypeMapping[inputs.soilType],
      cropType: cropTypeMapping[inputs.cropType],
    };
    
    // The Flask server will run on port 5000 by default
    const apiUrl = 'http://127.0.0.1:5000/predict';

    try {
      const response = await fetch(apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(dataToSend),
      });

      if (!response.ok) {
        throw new Error('Network response was not ok');
      }

      const data = await response.json();
      setResult(data.recommendation);
    } catch (error) {
      console.error('There was a problem with the fetch operation:', error);
      setResult("Error: Could not get a recommendation.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleChatSubmit = async () => {
    if (!chatInput.trim()) return;

    const userMessage = { sender: 'user', text: chatInput };
    const newChatHistory = [...chatHistory, userMessage];
    setChatHistory(newChatHistory);
    setChatInput('');
    setIsLoading(true);

    const dataToSend = { message: chatInput };
    const apiUrl = 'http://127.0.0.1:5000/chat';

    try {
      const response = await fetch(apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(dataToSend),
      });

      if (!response.ok) {
        throw new Error('Network response was not ok');
      }

      const data = await response.json();
      const botMessage = { sender: 'bot', text: data.response };
      setChatHistory(prevHistory => [...prevHistory, botMessage]);
    } catch (error) {
      console.error('Chatbot error:', error);
      const errorMessage = { sender: 'bot', text: "Sorry, I'm having trouble connecting right now. Please try again." };
      setChatHistory(prevHistory => [...prevHistory, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  const inputClass = "w-full p-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-green-500";
  const labelClass = "text-sm md:text-base font-semibold text-gray-700";

  const renderFormUI = () => (
    <>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-4">
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('temperature_label')}</label>
            <input 
              type="number" 
              name="temperature" 
              value={inputs.temperature} 
              onChange={handleInputChange} 
              className={inputClass}
            />
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('humidity_label')}</label>
            <input 
              type="number" 
              name="humidity" 
              value={inputs.humidity} 
              onChange={handleInputChange} 
              className={inputClass}
            />
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('moisture_label')}</label>
            <input 
              type="number" 
              name="moisture" 
              value={inputs.moisture} 
              onChange={handleInputChange} 
              className={inputClass}
            />
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('nitrogen_label')}</label>
            <input 
              type="number" 
              name="nitrogen" 
              value={inputs.nitrogen} 
              onChange={handleInputChange} 
              className={inputClass}
            />
          </div>
        </div>

        <div className="space-y-4">
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('soil_type_label')}</label>
            <select 
              name="soilType" 
              value={inputs.soilType} 
              onChange={handleInputChange} 
              className={inputClass}
            >
              <option value="Black">{i18n.t('soil_black')}</option>
              <option value="Clayey">{i18n.t('soil_clayey')}</option>
              <option value="Loamy">{i18n.t('soil_loamy')}</option>
              <option value="Sandy">{i18n.t('soil_sandy')}</option>
              <option value="Red">{i18n.t('soil_red')}</option>
            </select>
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('crop_type_label')}</label>
            <select 
              name="cropType" 
              value={inputs.cropType} 
              onChange={handleInputChange} 
              className={inputClass}
            >
              <option value="Barley">{i18n.t('crop_barley')}</option>
              <option value="Maize">{i18n.t('crop_maize')}</option>
              <option value="Wheat">{i18n.t('crop_wheat')}</option>
              <option value="Rice">{i18n.t('crop_rice')}</option>
              <option value="Cotton">{i18n.t('crop_cotton')}</option>
            </select>
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('potassium_label')}</label>
            <input 
              type="number" 
              name="potassium" 
              value={inputs.potassium} 
              onChange={handleInputChange} 
              className={inputClass}
            />
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('phosphorous_label')}</label>
            <input 
              type="number" 
              name="phosphorous" 
              value={inputs.phosphorous} 
              onChange={handleInputChange} 
              className={inputClass}
            />
          </div>
        </div>
      </div>
      
      <div className="mt-8 flex justify-center">
        <button
          onClick={handleFormPredict}
          disabled={isLoading}
          className="bg-green-600 hover:bg-green-700 text-white font-bold py-3 px-12 rounded-full transition-colors duration-300 shadow-lg text-lg focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {isLoading ? 'Predicting...' : i18n.t('predict_button')}
        </button>
      </div>

      <div className="mt-8 bg-white rounded-3xl shadow-xl p-6 w-full max-w-2xl text-center">
        <h2 className="text-xl md:text-2xl font-bold text-gray-800 mb-2">
          {i18n.t('result_header')}
        </h2>
        <p className="text-3xl md:text-4xl font-extrabold text-green-700">
          {result}
        </p>
      </div>
    </>
  );

  const renderChatUI = () => (
    <div className="flex flex-col h-[70vh] bg-white rounded-3xl shadow-xl p-6 md:p-12 max-w-2xl w-full">
      <div className="flex-1 overflow-y-auto mb-4 p-4 space-y-4 rounded-lg bg-gray-50 border border-gray-200">
        {chatHistory.map((message, index) => (
          <div key={index} className={`flex ${message.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`p-3 rounded-xl max-w-xs ${message.sender === 'user' ? 'bg-green-500 text-white' : 'bg-gray-200 text-gray-800'}`}>
              {message.text}
            </div>
          </div>
        ))}
      </div>
      <div className="flex space-x-2">
        <input 
          type="text" 
          value={chatInput}
          onChange={(e) => setChatInput(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && !isLoading && handleChatSubmit()}
          placeholder={i18n.t('chat_placeholder')}
          className="flex-1 p-3 border border-gray-300 rounded-full focus:outline-none focus:ring-2 focus:ring-green-500"
        />
        <button
          onClick={handleChatSubmit}
          disabled={isLoading}
          className="bg-green-600 hover:bg-green-700 text-white font-bold py-3 px-8 rounded-full transition-colors duration-300 shadow-lg text-lg disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {isLoading ? <div className="loader"></div> : i18n.t('chat_send_button')}
        </button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-cover bg-center bg-gray-200" style={{backgroundImage: "url('https://placehold.co/1920x1080/4F4/green?text=Plant+Background')"}}>
      <div className="absolute inset-0 bg-black opacity-60"></div>
      
      {/* Main Content Card */}
      <div className="relative z-10 flex flex-col items-center justify-center min-h-screen p-4 md:p-8">
        
        {/* Language and Mode Switcher */}
        <div className="w-full max-w-2xl flex justify-between items-center mb-6">
          <div className="flex items-center space-x-2">
            <label htmlFor="language-select" className="text-white font-medium">{i18n.t('change_language')}:</label>
            <select 
              id="language-select"
              value={currentLanguage}
              onChange={handleLanguageChange}
              className="p-2 border border-gray-300 rounded-lg shadow-sm text-gray-700 focus:outline-none focus:ring-2 focus:ring-green-500"
            >
              <option value="en">{i18n.t('language_en')}</option>
              <option value="pa">{i18n.t('language_pa')}</option>
              <option value="hi">{i18n.t('language_hi')}</option>
            </select>
          </div>
          <button
            onClick={toggleChatMode}
            className="bg-gray-700 hover:bg-gray-800 text-white font-bold py-2 px-6 rounded-full transition-colors duration-300 shadow-lg focus:outline-none focus:ring-2 focus:ring-gray-500"
          >
            {isChatMode ? i18n.t('switch_to_form_button') : i18n.t('switch_to_chat_button')}
          </button>
        </div>

        <div className="bg-white rounded-3xl shadow-xl p-6 md:p-12 max-w-2xl w-full">
            <div className="flex justify-center mb-6">
                 <h1 className="text-xl md:text-2xl font-bold text-gray-800 tracking-wide">
                    {isChatMode ? i18n.t('chat_title') : i18n.t('app_header')}
                 </h1>
            </div>
            {isChatMode ? renderChatUI() : renderFormUI()}
        </div>
      </div>
    </div>
  );
};

export default App;
